/* Authenticated local portal. No credentials, personal finances or documents in localStorage. */
(function(){
 'use strict';const app=document.getElementById('app'),notice=document.getElementById('notice'),dialog=document.getElementById('detail'),D=globalThis.RodavoltDriver;
 const inspectionSteps=new Map();let geoWatch=null,geoPending=false,geoLastSent=0,geoMessage='',commandQueue=Promise.resolve(),commandBusy=0,uploading=false;let dark=false;let session=null,data=null,tab='home',subpage='',users=[],files=[],pendingOffer=null;
 const currency=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:2}),currencyInput=new Intl.NumberFormat('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:6});
 const parseCurrency=value=>{const raw=String(value??'').trim().replace(/\s|R\$/g,'');const normalized=raw.includes(',')?raw.replace(/\./g,'').replace(',','.'): !/^[-+]?0\./.test(raw)&&/^-?\d{1,3}(?:\.\d{3})+$/.test(raw)?raw.replace(/\./g,''):raw;return /^-?\d+(?:\.\d+)?$/.test(normalized)?Number(normalized):NaN;};
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>currency.format(v||0),date=v=>String(v||'').split('-').reverse().join('/');
 const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18m-6 5h6"/>',shop:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};const icon=name=>`<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.more}</svg>`;
 const button=(label,action,extra='',primary=false)=>`<button type="button" data-action="${action}" ${extra} class="${primary?'primary':''}">${label}</button>`,field=(key,label,value='',type='text',extra='')=>{const monetary=type==='number'&&label.includes('R$'),shown=monetary&&value!==''&&value!==null&&value!==undefined?currencyInput.format(value):value;return `<label for="f-${key}">${label}</label><input id="f-${key}" name="${key}" type="${monetary?'text':type}" ${monetary?'inputmode="decimal" data-currency="true"':''} value="${esc(shown)}" ${monetary?extra.replace(/\s(?:step|min|max)="[^"]*"/g,''):extra}>`;},card=(title,body)=>`<section class="card"><h2>${title}</h2>${body}</section>`;
 function tell(message,error=false){notice.hidden=false;notice.classList.toggle('error',error);notice.textContent=message;}
 async function api(path,{method='GET',body,revision,key}={}){const headers={};if(body!==undefined)headers['Content-Type']='application/json';if(method!=='GET'&&session?.csrf)headers['x-csrf-token']=session.csrf;if(revision!==undefined)headers['If-Match']=String(revision);if(key)headers['Idempotency-Key']=key;const response=await fetch(path,{method,headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)});const value=await response.json();if(!response.ok){if(response.status===401){session=null;await start();}const error=new Error(value.error||'Não foi possível concluir.');error.status=response.status;throw error;}return value;}
 async function load(){data=await api('/api/workspace');if(session.user.role==='admin')users=(await api('/api/users')).users;files=(await api('/api/files')).files;render();}
 async function command(name,input,{quiet=false}={}){commandBusy++;const task=commandQueue.then(async()=>{try{data=await api('/api/command',{method:'POST',body:{command:name,input},revision:data.revision,key:crypto.randomUUID()});}catch(error){if(error.status===409){data=await api('/api/workspace');throw new Error('A operação recebeu uma atualização. Confira e tente enviar novamente. Seus campos continuam aqui.');}throw error;}if(!quiet){dialog.close();render();tell('Pronto. Seu registro foi salvo no servidor local.');}});commandQueue=task.catch(()=>{});try{return await task;}finally{commandBusy--;}}
 function open(title,body){document.getElementById('dialog-body').innerHTML=`<h2>${title}</h2>${body}`;if(!dialog.open)dialog.showModal();}
 function form(id,body,label){return `<form id="${id}">${body}<button type="submit" class="primary">${label}</button></form>`;}
 function authScreen(setup){document.body.classList.remove('driver-session');app.innerHTML=`<div class="narrow"><h1>${setup?'Prepare seu acesso à RODAVOLT':'Entre na RODAVOLT'}</h1><p>${setup?'Crie o acesso do proprietário. Depois você poderá criar o acesso de cada motorista.':'Use o acesso que a RODAVOLT preparou para você.'}</p>${card(setup?'Primeiro acesso':'Seu acesso',form(setup?'setup':'login',(setup?field('name','Seu nome','','text','required autocomplete="name"'):'')+field('username','Acesso','','text','required autocomplete="username"')+field('password','Senha','','password','required minlength="12" autocomplete="'+(setup?'new-password':'current-password')+'"')+'<p class="muted">Use uma senha de pelo menos 12 caracteres.</p>',setup?'Criar meu acesso':'Entrar'))}<p class="warning">Ambiente de homologação local. Começa com pessoas e valores fictícios. Banco, Pix, assinatura e rastreador ainda aguardam fornecedor e homologação.</p></div>`;}
 async function start(){session=await api('/api/session');if(!session.user)return authScreen(session.setupRequired);await load();}
 function render(){if(!session?.user)return;document.body.classList.toggle('driver-session',session.user.role==='driver');notice.hidden=true;app.innerHTML=session.user.role==='admin'?adminView():driverView();}
 function adminView(){const o=data.workspace.ops;return `<div class="topline"><h1>Olá, ${esc(session.user.name.split(' ')[0])}</h1>${button('Sair','logout')}</div><p>Operação salva no serviço local, com revisão de gravação e acessos separados.</p><a class="button primary" href="/operacao/gestao">Abrir painel completo da gestão →</a><div class="grid">${card('Acessos dos motoristas',`<p>Crie um acesso individual. Cada pessoa vê apenas seus registros.</p>${users.filter(u=>u.role==='driver').map(u=>`<div class="row"><span>${esc(u.name)}<small>${esc(u.username)} · ${u.disabled?'Desativado':'Ativo'}</small></span>${!u.disabled?button('Desativar','disable-user',`data-id="${u.id}"`):''}</div>`).join('')}${button('Criar acesso','new-user','',true)}`)}${card('Cópia de segurança',`<p>Exporta a operação e os arquivos privados. Não inclui senhas nem as finanças pessoais dos motoristas.</p>${button('Baixar backup','backup')}<details><summary>Restaurar uma cópia</summary><p>Substitui a operação. Os acessos e as senhas atuais são preservados. Faça um backup antes.</p>${form('restore',field('backup','Arquivo de backup','','file','required accept="application/json"')+'<label class="check"><input name="confirmed" type="checkbox" required>Conferi o backup e quero restaurá-lo.</label>','Restaurar operação')}</details>`)}${card('Documentos privados',files.map(f=>`<p><a href="/api/files/${f.id}">${esc(f.name)}</a> <small>${esc(o.drivers.find(d=>d.id===f.driverId)?.name||f.driverId)}</small></p>`).join('')||'<p>Nenhum arquivo enviado.</p>')}${card('Integrações',`<p>Banco/Pix, assinatura, telemetria e notificações: fornecedores ainda não configurados.</p><p class="muted">O painel completo permite validar os fluxos com dados de exemplo antes de conectar serviços.</p>`)}</div><div class="actions">${button('Trocar minha senha','password')}${button('Ver trilha de gravações','audit')}</div>`;}
 function driverView(){const v=data.driver,main=subpage?driverSubpage(v):({home:home,wallet:wallet,shop:shop,more:more}[tab])(v),title={wallet:'Meu aluguel',shop:'Minha lojinha',more:'Minha RODAVOLT'}[tab];return `<div class="narrow"><header class="driver-header"><div><p class="eyebrow">${tab==='home'&&!subpage?'BEM-VINDO À SUA RODAVOLT':'SEU ESPAÇO'}</p><h1>${subpage?'Vamos cuidar disso':title||'Olá, '+esc(v.profile.name.split(' ')[0])}</h1><p class="muted">${subpage?'Uma etapa de cada vez.':'Mais tranquilidade para rodar.'}</p></div>${button(dark?'☀':'☾','theme','aria-label="Alternar tema"')}</header>${subpage?button('← Voltar ao início','back'):''}${main}<p class="privacy-note">Seu acesso é individual. Você vê apenas seus registros.</p></div><nav class="tabs" aria-label="Navegação do motorista">${[['home','Início'],['wallet','Aluguel'],['shop','Lojinha'],['more','Mais']].map(([key,label])=>`<button data-action="tab" data-tab="${key}" ${tab===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span></button>`).join('')}</nav>`; }
 function rent(v){const q=v.charges.find(c=>c.status!=='paid'&&c.balance>0);return `<section class="card rent-card"><p class="eyebrow">${q?'SEU ALUGUEL DA SEMANA':'MEU ALUGUEL'}</p><div class="money">${q?money(q.balance):'Tudo em dia'}</div><p>${q?'Vence em '+date(q.date):'Nenhuma cobrança pendente por enquanto.'}</p>${q?.periodStart?`<p class="rent-period">Pela semana utilizada de ${date(q.periodStart)} a ${date(q.finalPeriodEnd||q.periodEnd)}</p>`:''}${tab!=='wallet'?button('Ver meu aluguel →','tab','data-tab="wallet"',true):''}</section>`; }
 function home(v){if(v.profile.stage==='closed')return card('Estamos aqui para ajudar','<p>Seu vínculo foi encerrado. Seus saldos e documentos continuam disponíveis.</p>'+button('Ver meus saldos','tab','data-tab="wallet"',true)+button('Meus contratos','subpage','data-page="contracts"')+button('Pedir ajuda','subpage','data-page="support"'))+rent(v);const active=v.profile.stage==='active',last=v.journey?.checkins?.[0],pending=v.inventory.combos.some(c=>c.status==='sent'),agenda=v.agenda.filter(e=>!['done','cancelled'].includes(e.status))[0];return `<section class="car-strip"><span class="car-symbol" aria-hidden="true">⚡</span><div><strong>${esc(v.vehicle?.model||'Seu próximo carro')}</strong><small>${esc(v.vehicle?.plate||v.vehicle?.id||'Aguardando definição da RODAVOLT')} · elétrico</small></div>${button('Ver','subpage','data-page="care"')}</section>${active?`<section class="start-card"><div><p class="eyebrow">ANTES DE SAIR</p><h2>Pronto para o seu dia?</h2><p>${last?'Último check-in em '+esc(new Date(last.at||last.createdAt).toLocaleString('pt-BR')):'Confira o carro e avise que está tudo certo.'}</p></div>${button('Fazer check-in','checkin','',true)}</section>`:card('Seu caminho até o carro','<p>A equipe vai conferir cadastro, contrato, caução e vistoria com você.</p>'+button('Ver meu contrato','subpage','data-page="contracts"',true)+button('Fazer vistoria','subpage','data-page="inspection"'))}${rent(v)}${pending?`<button class="stock-nudge" data-action="tab" data-tab="shop">Chegou um combo para você. Confira os produtos →</button>`:''}<div class="section-title"><h2>O que vamos fazer?</h2><small>Um toque para começar</small></div><div class="driver-action-grid">${[['shop','Vender produto','Seu lucro, no seu bolso','shop'],['inspection','Fazer vistoria','Fotos e itens do carro','home'],['ride','Conferir corrida','Saiba quanto vai sobrar','wallet'],['contracts','Meus contratos','Leia e envie assinado','more']].map(([key,title,small,symbol])=>`<button class="big-action" data-action="${key==='shop'?'tab':'subpage'}" ${key==='shop'?'data-tab':'data-page'}="${key}"><span class="action-icon">${icon(symbol)}</span><strong>${title}</strong><span>${small}</span><b aria-hidden="true">↗</b></button>`).join('')}</div>${active?locationCard(v):''}${agenda?card('Seu próximo compromisso',`<strong>${esc(agenda.title)}</strong><p>${date(agenda.date)} · ${esc(agenda.time)}</p>${button('Ver compromissos','subpage','data-page="agenda"')}`):''}<button class="help-strip" data-action="subpage" data-page="support">Precisou? Fale com a RODAVOLT <span>→</span></button>`; }
 function wallet(v){return rent(v)+card('Desconto da lojinha',`<div class="money">${money(v.credits.available)}</div><p>Pronto para usar no aluguel, depois de conferir as vendas.</p>${v.credits.available>0?v.charges.filter(q=>q.status!=='paid'&&q.balance>0).slice(0,1).map(q=>button('Usar no meu aluguel','use-credit',`data-id="${q.id}"`,true)).join(''):''}`)+card('Meus aluguéis',v.charges.slice().reverse().map(q=>`<div class="row"><span>${date(q.date)}<small>${q.periodStart?date(q.periodStart)+' a '+date(q.finalPeriodEnd||q.periodEnd):'Histórico de abertura'}</small></span><strong>${q.status==='paid'?'Conferido':money(q.balance)}</strong>${q.status!=='paid'&&q.balance>0?button('Já paguei','proof',`data-id="${q.id}"`):''}</div>`).join(''))+card('Minha caução',`<p>Dinheiro de garantia separado do aluguel.</p><strong>${money(v.deposit.balance)}</strong><p class="muted">A devolução é conferida pela gestão no encerramento.</p>`);}
 function shop(v){return '<section class="shop-intro"><p class="eyebrow">SUA RENDA EXTRA</p><h2>Produtos no carro.<br>Lucro para você.</h2><p>Escolha o produto, registre a venda e acompanhe seu ganho.</p></section>'+ v.inventory.combos.filter(c=>c.status==='sent').map(c=>card('Chegou um combo para você',c.lines.map(l=>`<p>${esc(l.name)} · ${l.sent} unidade(s)</p>`).join('')+button('Conferir produtos','receive-combo',`data-id="${c.id}"`,true))).join('')+v.inventory.orders.filter(o=>o.status==='awaiting_payment'||o.status==='paid'&&!o.deliveredAt).map(o=>card(o.status==='awaiting_payment'?'Aguardando pagamento':'Pode entregar o produto',`<div class="money">${money(o.gross)}</div><p>${o.lines.map(l=>l.qty+' × '+esc(l.name)).join('<br>')}</p>${o.status==='awaiting_payment'?'<p>Pix ainda não conectado. A gestão confere o pagamento de teste.</p>'+button('Cancelar esta compra','cancel-order',`data-id="${o.id}"`):button('Entreguei o produto','deliver-order',`data-id="${o.id}"`,true)}`)).join('')+card('Seus produtos para vender',v.inventory.products.map(p=>`<div class="row"><span><strong>${esc(p.name)}</strong><small>${money(p.price)} · Você tem ${p.available} para vender</small>${p.expired?'<small class="error">Fora da validade. Avise a RODAVOLT.</small>':''}${p.driverProfit!==null&&p.driverProfit!==undefined?`<small>Seu lucro: ${money(p.driverProfit)} por unidade</small>`:''}</span>${p.available>0&&!p.expired?button('Vender','sell',`data-id="${p.id}"`):''}</div>`).join(''))+card('Pedir mais produtos',form('stock-request',`<label for="stock-product">Qual produto?</label><select id="stock-product" name="productId">${v.inventory.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select>${field('qty','Quantas unidades?',2,'number','required min="1" step="1"')}${field('note','Observação','Reposição do meu kit','text','required')}`,'Pedir reposição'));
 }
 function more(v){return `<div class="connection-actions">${v.profile.stage==='active'?button('Fazer check-in','checkin','',true)+button('Minha localização','location-open'):''}</div>`+[['Meu trabalho',[['ride','Conferir uma corrida'],['day','Anotar meu dia'],['goals','Minha meta e meus custos']]],['Meu carro',[['inspection','Fazer vistoria'],['care','Cuidar do carro'],['agenda','Meus compromissos'],['closure','Devolver o carro']]],['Minha RODAVOLT',[['contracts','Meus contratos'],['support','Pedir ajuda'],['files','Meus arquivos']]]].map(([title,links])=>card(title,links.map(([key,label])=>`<button class="menu-link" data-action="subpage" data-page="${key}">${label}<span>→</span></button>`).join(''))).join('')+`<div class="actions">${button('Trocar minha senha','password')}${button('Sair da minha conta','logout')}</div>`; }
 function driverSubpage(v){if(subpage==='agenda')return card('Meus compromissos',`<p class="muted">Horários da operação: ${esc(v.timeZone)}.</p>`+v.agenda.map(e=>`<div class="row"><span>${esc(e.title)}<small>${date(e.date)} · ${e.time} · ${e.status==='done'?'Concluído':'A fazer'}</small></span></div>`).join(''));
 if(subpage==='contracts')return '<div class="process"><span>1 · Leia</span><span>2 · Assine fora do app</span><span>3 · Envie aqui</span></div><p class="muted">Se assinar pelo GOV.BR, volte com o PDF assinado. A RODAVOLT confere o arquivo antes de concluir.</p>'+card('Meus contratos',v.contracts.map(c=>{const returns=(v.journey?.contractReturns||[]).filter(r=>r.contractId===c.id),last=returns[0];return `<article class="contract-item"><h3>${esc(c.title)}</h3><p class="document-status">${last?({awaiting_review:'PDF recebido · aguardando conferência',accepted:'Arquivo conferido pela RODAVOLT',changes:'Precisamos de um novo arquivo'}[last.status]||esc(last.status)):esc(c.statusLabel)}</p>${last?.review?.note?`<p class="warning">${esc(last.review.note)}</p>`:''}<div class="actions">${button('Ler contrato','contract-read',`data-id="${c.id}"`)}${!['cancelled','refused','expired'].includes(c.status)?button('Enviar PDF assinado','contract-upload',`data-id="${c.id}"`,true):''}${last?`<a class="button" href="/api/files/${last.fileId}" target="_blank" rel="noopener">Ver PDF enviado</a>`:''}</div><details><summary>Histórico e conferência</summary>${returns.map(r=>`<p>${esc(new Date(r.submittedAt).toLocaleString('pt-BR'))} · ${esc(r.fileName)} · ${esc(r.status==='awaiting_review'?'Aguardando conferência':r.status==='accepted'?'Conferido':'Correção solicitada')}</p>`).join('')||'<p>Nenhum PDF enviado ainda.</p>'}<p class="muted">Receber o PDF não valida automaticamente a assinatura.</p></details></article>`;}).join('')||'<p>A RODAVOLT vai preparar seu contrato. Quando estiver pronto, aparecerá aqui.</p>');
 if(subpage==='support'||subpage==='care')return (subpage==='care'&&v.maintenance.length?card('Próximos cuidados',v.maintenance.map(p=>`<p><strong>${esc(p.title)}</strong><br>${p.nextDate?date(p.nextDate):''}${p.nextDate&&p.nextKm!==null?' ou ':''}${p.nextKm===null?'':p.nextKm+' km'}${p.openOrderId?'<br>Oficina agendada':''}</p>`).join('')):'')+card(subpage==='care'?'Cuidar do carro':'Pedir ajuda',form('support',`<input type="hidden" name="type" value="${subpage==='care'?'maintenance':'support'}"><label for="note">Conte o que aconteceu</label><textarea id="note" name="note" required maxlength="500"></textarea><label for="priority">Você consegue trabalhar?</label><select id="priority" name="priority"><option value="normal">Sim</option><option value="urgent">Não, preciso de ajuda</option></select>`,'Enviar pedido'))+card('Meus pedidos e respostas',v.requests.map(r=>`<p><strong>${esc(r.note)}</strong><br>${esc(r.reply||'Aguardando resposta da RODAVOLT.')}</p>`).join('')||'<p>Nenhum pedido por enquanto.</p>');
 if(subpage==='closure')return card('Devolver o carro',v.closures.length?v.closures.map(c=>`<p>${date(c.scheduledDate||c.date)} · ${c.status==='closed'?'Devolução concluída':'Conferência em andamento'}</p><p>${esc(c.note||'A RODAVOLT vai orientar os próximos passos.')}</p>`).join(''):'<p>Peça ajuda para combinar a devolução. O carro, os produtos e os saldos serão conferidos com você.</p>')+button('Combinar devolução','subpage','data-page="support"',true);
 if(subpage==='goals')return card('Minha meta e meus custos',form('goals',Object.entries(D.defaults).map(([key])=>field(key,({goalDay:'Quero que sobre por dia · R$',energyPriceKWh:'Recarga · R$/kWh',consumptionKWh100Km:'Consumo · kWh/100 km',chargingLossPct:'Perda na recarga · %',weeklyRent:'Aluguel por semana · R$',workDays:'Dias de trabalho por semana',hoursDay:'Horas por dia',plannedKmDay:'Km por dia',minNetKm:'Quero que sobre por km · R$',minNetHour:'Quero que sobre por hora · R$',otherPerKm:'Outros custos por km · R$'})[key],v.personal.settings[key],'number',`required min="${D.limits[key][0]}" max="${D.limits[key][1]}" step="any"`)).join(''),'Salvar minha meta'));
 if(subpage==='day')return card('Como foi seu dia?',form('journey',field('date','Qual dia?','2027-01-25','date','required')+[['amount','Quanto recebeu? · R$',400],['energyKWh','Energia carregada · kWh',25],['energyPriceKWh','Preço da recarga · R$/kWh',v.personal.settings.energyPriceKWh??D.defaults.energyPriceKWh],['other','Outras despesas · R$',10],['km','Km rodados',150],['hours','Horas trabalhadas',8]].map(([key,label,value])=>field(key,label,value,'number','required min="0" step="any"')).join(''),'Salvar meu dia'))+card('O que sobrou',`<div class="money">${money(D.daySummary(v.personal.journeys,v.personal.settings).net)}</div><p>Depois dos custos e do aluguel dos dias anotados. Só você vê estes registros.</p>`);
 if(subpage==='ride')return card('Vale esta corrida?',form('ride',[['amount','Quanto vai receber? · R$',32],['pickupKm','Km para buscar',2],['tripKm','Km da viagem',10],['pickupMin','Minutos para buscar',6],['tripMin','Minutos da viagem',22],['waitMin','Minutos de espera',0],['returnKm','Km de retorno',0],['returnMin','Minutos de retorno',0],['toll','Pedágio não reembolsado · R$',0]].map(([key,label,value])=>field(key,label,value,'number','required min="0" step="any"')).join(''),'Conferir corrida'));
 if(subpage==='inspection')return inspection(v);
 if(subpage==='files')return button('Baixar meus registros pessoais','personal-export')+card('Meus arquivos',files.map(f=>`<p><a href="/api/files/${f.id}">${esc(f.name)}</a></p>`).join('')||'<p>Nenhum arquivo enviado.</p>');return '';
 }
 function locationText(v){const point=v.journey?.location;if(geoMessage)return geoMessage;if(!point?.sharing)return 'Você escolhe quando começar e quando parar.';const age=Math.max(0,Date.now()-Date.parse(point.capturedAt));return age>120000?'Última posição antiga. Abra o compartilhamento para atualizar.':'Posição recebida às '+new Date(point.capturedAt).toLocaleTimeString('pt-BR')+'.';}
 function locationCard(v){return `<section class="card location-card"><p class="eyebrow">LOCALIZAÇÃO DO CARRO</p><h2>${geoWatch!==null?'Compartilhando com a RODAVOLT':'Você controla o compartilhamento'}</h2><p data-location-status>${esc(locationText(v))}</p>${button('Ver compartilhamento','location-open')}<small>Funciona enquanto esta página está aberta, com sua permissão. Não funciona como rastreador em segundo plano.</small></section>`;}
 function locationDialog(){open('Compartilhar minha localização',`<p>A RODAVOLT verá sua posição e a precisão informada pelo celular. Use com o carro parado.</p><p data-location-status>${esc(locationText(data.driver))}</p><p class="warning">Mantenha esta página aberta. Se o celular suspender o navegador, as atualizações podem parar. Você pode interromper a qualquer momento.</p><div class="actions">${geoWatch===null?button('Permitir e começar','location-start','',true):''}${button('Parar e remover minha posição','location-stop')}</div>`);}
 function updateLocationLabel(){document.querySelectorAll('[data-location-status]').forEach(e=>{e.textContent=locationText(data.driver);});}
 function clearWatch(){if(geoWatch!==null)navigator.geolocation.clearWatch(geoWatch);geoWatch=null;}
 function startLocation(){if(!navigator.geolocation)throw new Error('Este navegador não oferece localização.');if(!window.isSecureContext)throw new Error('Para usar a localização, abra por HTTPS ou no endereço local desta máquina.');if(geoWatch!==null)return;geoMessage='Aguardando sua permissão e a primeira posição…';updateLocationLabel();geoWatch=navigator.geolocation.watchPosition(async position=>{if(geoPending||Date.now()-geoLastSent<15000||uploading)return;geoPending=true;try{await command('location.share',{latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:position.coords.accuracy,capturedAt:new Date(position.timestamp).toISOString()},{quiet:true});geoLastSent=Date.now();geoMessage='';}catch(error){geoMessage='Não foi possível atualizar: '+error.message;}finally{geoPending=false;updateLocationLabel();}},async error=>{clearWatch();geoMessage=error.code===1?'Permissão negada. Você pode permitir novamente nas configurações do navegador.':'Não conseguimos obter sua posição. Tente novamente com sinal disponível.';try{await command('location.stop',{}, {quiet:true});}catch{}updateLocationLabel();if(dialog.querySelector('[data-location-status]'))locationDialog();},{enableHighAccuracy:true,maximumAge:10000,timeout:20000});locationDialog();}
 async function uploadPrivate(file,metadata){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return api('/api/files',{method:'POST',body:{...metadata,name:file.name,mime:file.type||'application/pdf',content:btoa(binary)}});}
 const inspectionItems=[['tires','Pneus, rodas e estepe'],['brakes','Freios e painel'],['lights','Faróis e lanternas'],['body','Lataria e vidros'],['interior','Bancos e interior'],['charging','Porta de recarga, cabo e alertas da bateria'],['kit','Produtos do kit'],['equipment','Chaves e segurança']],slots=[['front','Frente'],['rear','Traseira'],['left','Lado esquerdo'],['right','Lado direito'],['dashboard','Painel e hodômetro']];
 function inspection(v){
  const draft=v.inspections.find(r=>['draft','changes_requested'].includes(r.status));
  if(!draft)return card('Fazer vistoria',`<p>Faça com o carro parado. Vamos conferir em quatro passos.</p>${form('inspection-create','<label for="inspection-type">Qual vistoria?</label><select name="type" id="inspection-type"><option value="periodic">Conferência de rotina</option><option value="delivery">Receber o carro</option><option value="return">Devolver o carro</option></select>','Começar vistoria')}`)+card('Minhas vistorias',v.inspections.map(r=>`<p>${date(r.createdAt.slice(0,10))} · ${r.status==='approved'?'Conferida pela gestão':r.status==='submitted'?'Aguardando conferência':'Em preenchimento'}</p>`).join(''));
  const step=inspectionSteps.get(draft.id)||1,titles=['Vamos conferir o painel','Como está o carro?','Agora, as fotos','Está tudo certo?'];
  const body=step===1?field('km','Quantos km aparecem no painel?',draft.km,'number','required min="0" step="1"')+field('chargePct','Carga da bateria no painel · %',draft.chargePct,'number','required min="0" max="100" step="1"')+'<p class="muted">Bateria cheia = 100%. Informe a carga mostrada no painel.</p>':step===2?inspectionItems.map(([key,label])=>`<label for="item-${key}">${label}</label><select name="${key}" id="item-${key}" required>${[['','Escolha'],['ok','Tudo certo'],['damage','Tem problema'],['na','Não se aplica']].map(([value,text])=>`<option value="${value}" ${draft.items[key]===value?'selected':''}>${text}</option>`).join('')}</select>`).join('')+`<label for="inspection-note">Encontrou um problema? Conte aqui.</label><textarea id="inspection-note" name="note">${esc(draft.note)}</textarea>`:step===3?'<p>São cinco fotos, uma de cada vez. Use imagens de teste durante a homologação.</p>'+slots.map(([key,label])=>field(key,label,'','file','accept="image/png,image/jpeg" capture="environment"')+(draft.evidence.some(e=>e.slot===key)?'<small>Foto incluída neste rascunho. Escolha outra somente se precisar trocar.</small>':'<small>Ainda falta esta foto.</small>')).join(''):`<div class="row"><span>Km no painel</span><strong>${draft.km} km</strong></div><div class="row"><span>Carga da bateria</span><strong>${draft.chargePct}%</strong></div><div class="row"><span>Itens conferidos</span><strong>${inspectionItems.filter(([key])=>draft.items[key]).length} de 8</strong></div><div class="row"><span>Fotos privadas</span><strong>${draft.evidence.length} de 5</strong></div>${draft.note?`<p>${esc(draft.note)}</p>`:''}<p>A RODAVOLT vai conferir. Enviar não libera o carro sozinho.</p><label class="check"><input name="submitNow" type="checkbox" required>Conferi as informações e quero enviar.</label>`;
  return card(titles[step-1],`<p class="muted">Passo ${step} de 4</p><progress max="4" value="${step}" aria-label="Etapas da vistoria"></progress><form id="inspection-save"><input type="hidden" name="id" value="${draft.id}"><input type="hidden" name="step" value="${step}">${body}<div class="actions">${step>1?'<button type="submit" name="direction" value="back" formnovalidate>← Voltar</button>':''}<button type="submit" class="primary">${step===4?'Enviar vistoria':'Continuar →'}</button><button type="submit" name="direction" value="pause" formnovalidate>Salvar para continuar depois</button></div><p class="muted">O rascunho e as fotos enviadas ficam no seu acesso individual.</p></form>`);
 }
 function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());
 document.addEventListener('click',async event=>{const e=event.target.closest('[data-action]');if(!e)return;try{const action=e.dataset.action,v=data?.driver;
  if(action==='theme'){dark=!dark;document.documentElement.classList.toggle('dark',dark);render();return;}if(action==='logout'){clearWatch();if(session?.user?.role==='driver'&&data?.driver?.journey?.location?.sharing){await command('location.stop',{}, {quiet:true});}await api('/api/logout',{method:'POST',body:{}});session=null;data=null;return start();}
  if(action==='tab'){tab=e.dataset.tab;subpage='';render();window.scrollTo(0,0);return;}if(action==='subpage'){subpage=e.dataset.page;render();window.scrollTo(0,0);return;}if(action==='back'){subpage='';render();return;}
  if(action==='checkin'){if(!v.vehicle)throw new Error('Aguarde o vínculo do seu carro.');open('Antes de sair',form('checkin',`<p>Faça com o carro parado. Informe o que aparece no painel.</p>${field('km','Km no painel',v.vehicle.km,'number',`required min="${v.vehicle.km}" step="1"`)}${field('battery','Carga da bateria · %','','number','required min="0" max="100" step="1"')}${field('note','Algo que precisamos saber?','','text','maxlength="500"')}<p class="muted">O check-in atualiza o hodômetro e aparece para a RODAVOLT. Se houver um problema, peça manutenção.</p>`,'Confirmar check-in'));return;}
  if(action==='location-open'){locationDialog();return;}if(action==='location-start'){startLocation();return;}if(action==='location-stop'){clearWatch();await command('location.stop',{});geoMessage='Compartilhamento encerrado. Sua posição foi removida do painel.';tell(geoMessage);return;}
  if(action==='contract-read'){const c=v.contracts.find(c=>c.id===e.dataset.id);if(!c)throw new Error('Contrato não encontrado.');open(c.title,`<p class="muted">Minuta para revisão. Confira os dados e as condições com a RODAVOLT.</p><pre>${esc(c.preview)}</pre>`);return;}
  if(action==='contract-upload'){const c=v.contracts.find(c=>c.id===e.dataset.id);if(!c)throw new Error('Contrato não encontrado.');open('Devolver contrato assinado',form('contract-return',`<input type="hidden" name="contractId" value="${c.id}"><h3>${esc(c.title)}</h3><p>Selecione o PDF que você assinou fora do app, por exemplo pelo GOV.BR. O arquivo fica privado neste serviço local.</p>${field('document','PDF assinado','','file','accept="application/pdf,.pdf" required')}<p class="muted">Até 5 MB. A equipe vai conferir o documento; este envio não valida a assinatura automaticamente.</p><label class="check"><input type="checkbox" name="confirmed" required>Conferi que este é o meu contrato assinado.</label>`,'Enviar para a RODAVOLT'));return;}
  if(action==='new-user'){open('Criar acesso do motorista',form('new-user',`<label for="user-driver">Motorista</label><select name="driverId" id="user-driver">${data.workspace.ops.drivers.filter(dr=>!users.some(u=>u.driverId===dr.id&&!u.disabled)).map(dr=>`<option value="${dr.id}">${esc(dr.name)}</option>`).join('')}</select>${field('username','Acesso','','text','required pattern="[a-z0-9][a-z0-9._-]{2,59}"')}${field('password','Senha inicial','','password','required minlength="12" autocomplete="new-password"')}<p>Combine a entrega do acesso diretamente com o motorista. Ele poderá trocar a senha.</p>`,'Criar acesso'));return;}
  if(action==='disable-user'){await api('/api/users/disable',{method:'POST',body:{id:e.dataset.id}});await load();tell('Acesso desativado. As sessões anteriores foram encerradas.');return;}
  if(action==='personal-export'){download(await api('/api/personal/export'),'meus-registros-rodavolt.json');return;}if(action==='backup'){download(await api('/api/backup'),'rodavolt-backup-local.json');return;}if(action==='audit'){const log=await api('/api/audit');open('Histórico de gravações',log.events.slice().reverse().map(e=>`<p><strong>${esc(e.action)}</strong><br>${esc(new Date(e.at).toLocaleString('pt-BR'))}</p>`).join(''));return;}
  if(action==='password'){open('Trocar minha senha',form('password',field('currentPassword','Senha atual','','password','required autocomplete="current-password"')+field('password','Nova senha','','password','required minlength="12" autocomplete="new-password"'),'Salvar nova senha'));return;}
  if(action==='use-credit'){const q=v.charges.find(q=>q.id===e.dataset.id),amount=Math.min(q.balance,v.credits.available);open('Usar meu desconto',form('credit',`<input type="hidden" name="chargeId" value="${q.id}"><p>Aluguel: ${money(q.balance)}</p><p>Desconto: ${money(amount)}</p><h3>Depois, falta pagar ${money(q.balance-amount)}</h3>`,'Sim, usar meu desconto'));return;}
  if(action==='proof'){open('Avisar que já paguei',form('proof',`<input type="hidden" name="chargeId" value="${e.dataset.id}">${field('note','Referência ou observação','','text','required maxlength="500"')}<p>A RODAVOLT vai conferir. Este aviso não confirma o pagamento.</p>`,'Enviar para conferência'));return;}
  if(action==='sell'){const p=v.inventory.products.find(p=>p.id===e.dataset.id);open('Vender '+p.name,form('order',`<input type="hidden" name="productId" value="${p.id}"><p>${money(p.price)} por unidade</p>${field('qty','Quantas unidades?',1,'number',`required min="1" max="${p.available}" step="1"`)}<p>O produto fica reservado. Entregue depois da confirmação do pagamento.</p>`,'Mostrar pagamento'));return;}
  if(action==='receive-combo'){const c=v.inventory.combos.find(c=>c.id===e.dataset.id);open('Conferir os produtos',form('combo',`<input type="hidden" name="id" value="${c.id}">${c.lines.map(l=>field(l.productId,l.name+' · enviado '+l.sent,l.sent,'number',`required min="0" max="${l.sent}" step="1"`)).join('')}${field('note','Se algo estiver diferente, conte aqui')}<p>Confirme somente a quantidade que chegou boa para vender.</p>`,'Confirmar recebimento'));return;}
  if(action==='cancel-order')return await command('order.cancel',{id:e.dataset.id});if(action==='deliver-order')return await command('order.deliver',{id:e.dataset.id});if(action==='sign'){open('Testar minha assinatura',form('signature',`<input type="hidden" name="id" value="${e.dataset.id}"><label class="check"><input type="checkbox" name="confirmed" required>Li o documento demonstrativo. Entendi que este teste não assina um contrato real.</label>`,'Registrar teste'));return;}
  if(action==='ride-choice'){await command('ride',{offer:pendingOffer,choice:e.dataset.choice});pendingOffer=null;return;}
 }catch(error){tell(error.message,true);}});
 document.addEventListener('submit',async event=>{if(!(event.target instanceof HTMLFormElement))return;event.preventDefault();const f=event.target,formId=f.getAttribute('id'),values=new FormData(f);for(const field of (f.querySelectorAll?.('[data-currency]')||[])){const parsed=parseCurrency(field.value);if(!Number.isFinite(parsed)){tell('Informe um valor em reais, por exemplo 1.000,00.',true);return;}values.set(field.name,String(parsed));}const input=Object.fromEntries(values);const numeric=keys=>Object.fromEntries(keys.map(key=>[key,Number(values.get(key))]));const submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;try{
  if(formId==='setup'||formId==='login'){const result=await api('/api/'+formId,{method:'POST',body:input});session={...session,...result};await load();return;}
  if(formId==='checkin')return await command('checkin',{km:Number(input.km),battery:Number(input.battery),note:input.note});
  if(formId==='contract-return'){const file=values.get('document');if(!input.confirmed||!file?.size)throw new Error('Selecione o PDF e confirme o envio.');if(file.size>5*1024*1024||!(file.type==='application/pdf'||!file.type&&file.name.toLowerCase().endsWith('.pdf')))throw new Error('Escolha um PDF de até 5 MB.');uploading=true;try{await commandQueue;const uploaded=await uploadPrivate(file,{contractId:input.contractId});data=await api('/api/workspace');await command('contract.return',{contractId:input.contractId,fileId:uploaded.file.id});files=(await api('/api/files')).files;tell('PDF recebido. A RODAVOLT vai conferir e responder por aqui.');}finally{uploading=false;}return;}
  if(formId==='new-user'){await api('/api/users',{method:'POST',body:input});dialog.close();await load();tell('Acesso criado. O motorista já pode entrar pelo endereço local.');return;}
  if(formId==='password'){const result=await api('/api/password',{method:'POST',body:input});session.csrf=result.csrf;dialog.close();tell('Senha atualizada e demais sessões encerradas.');return;}
  if(formId==='restore'){const file=values.get('backup');if(!input.confirmed||!file?.size)throw new Error('Escolha o backup e confirme a restauração.');await api('/api/restore',{method:'POST',body:JSON.parse(await file.text()),revision:data.revision});await start();tell('Backup restaurado. Entre novamente para conferir.');return;}
  if(formId==='credit'||formId==='proof')return await command(formId,input);
  if(formId==='support')return await command('request',input);
  if(formId==='stock-request')return await command('request',{...input,type:'stock',qty:Number(input.qty)});
  if(formId==='order')return await command('order.create',{lines:[{productId:input.productId,qty:Number(input.qty)}]});
  if(formId==='combo'){const c=data.driver.inventory.combos.find(c=>c.id===input.id);return await command('combo.receive',{id:c.id,lines:c.lines.map(l=>({productId:l.productId,qty:Number(input[l.productId])})),note:input.note});}
  if(formId==='goals')return await command('goals',numeric(Object.keys(D.defaults)));
  if(formId==='journey')return await command('journey',{date:input.date,...numeric(['amount','energyKWh','energyPriceKWh','other','km','hours'])});
  if(formId==='ride'){pendingOffer=numeric(['amount','pickupKm','tripKm','pickupMin','tripMin','waitMin','returnKm','returnMin','toll']);const result=D.evaluate(pendingOffer,data.driver.personal.settings);open('Veja se compensa',`<h3>${result.meets?'Dentro da sua meta':'Abaixo da sua meta'}</h3><p>Sobra: <strong>${money(result.net)}</strong></p><p>${money(result.netKm)} por km · ${money(result.netHour)} por hora</p><p>Oferta mínima para sua meta: ${money(result.minimumOffer)}</p><div class="actions">${button('Vou aceitar','ride-choice','data-choice="accepted"',true)}${button('Vou recusar','ride-choice','data-choice="rejected"')}</div><p class="muted">Anote a decisão aqui e faça sua escolha no app de transporte, com o carro parado.</p>`);return;}
  if(formId==='signature')return await command('contract.signature',{id:input.id});
  if(formId==='inspection-create')return await command('inspection.create',{type:input.type});
  if(formId==='inspection-save'){
   const draft=data.driver.inspections.find(r=>r.id===input.id),step=Number(input.step),direction=event.submitter?.value;
   if(direction==='back'){inspectionSteps.set(draft.id,Math.max(1,step-1));render();tell('Voltamos ao último rascunho salvo.');return;}
   const items={...draft.items,...Object.fromEntries(inspectionItems.filter(([key])=>values.has(key)).map(([key])=>[key,input[key]]))},note=values.has('note')?input.note:draft.note,evidence=draft.evidence.slice();
   if(direction!=='pause'&&step===2){if(inspectionItems.some(([key])=>!items[key]))throw new Error('Escolha uma resposta para cada item do carro.');if(Object.values(items).includes('damage')&&!note.trim())throw new Error('Conte qual problema você encontrou.');}
   const uploads=slots.filter(([slot])=>values.get(slot)?.size);for(const [slot]of uploads){const file=values.get(slot);if(!['image/png','image/jpeg'].includes(file.type)||file.size>5*1024*1024)throw new Error('Use fotos PNG ou JPEG de até 5 MB.');}
   if(direction!=='pause'&&step===3&&new Set([...evidence.map(e=>e.slot),...uploads.map(([slot])=>slot)]).size<5)throw new Error('Ainda faltam fotos. Inclua as cinco vistas do carro.');
   for(const [slot]of uploads){const file=values.get(slot),bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);const uploaded=await api('/api/files',{method:'POST',body:{name:file.name,mime:file.type,content:btoa(binary),inspectionId:draft.id,slot}});const index=evidence.findIndex(e=>e.slot===slot),item={slot,source:'private',fileId:uploaded.file.id};if(index<0)evidence.push(item);else evidence[index]=item;}
   data=await api('/api/workspace');await command('inspection.save',{id:draft.id,km:values.has('km')?Number(input.km):draft.km,chargePct:values.has('chargePct')?Number(input.chargePct):draft.chargePct,items,note,evidence});
   if(direction==='pause'){subpage='';render();tell('Vistoria salva. Você pode continuar depois.');return;}
   if(step<4){inspectionSteps.set(draft.id,step+1);render();window.scrollTo(0,0);}else{if(!input.submitNow)throw new Error('Confira as informações antes de enviar.');await command('inspection.submit',{id:draft.id});inspectionSteps.delete(draft.id);tell('Vistoria enviada. A RODAVOLT vai conferir.');}return;
  }

 }catch(error){tell(error.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});
 // Refresh visible balances without interrupting a form, inspection, upload or command.
 setInterval(async()=>{if(session?.user?.role!=='driver'||subpage||dialog.open||commandBusy||uploading||document.hidden)return;try{const next=await api('/api/workspace');if(commandBusy||uploading||dialog.open)return;data=next;render();}catch(error){tell(error.message,true);}},15000);
 window.addEventListener('pagehide',clearWatch);
 start().catch(error=>tell(error.message,true));
})();
